		/** 
		 * Tests creating a new Order.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Order");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Order" );

			try {            
				Order entity = OrderService.getOrderInstance().createOrder( generateNewEntity() );
				thePrimaryKey = entity.getOrderId();
				LOGGER.info( "-- Successfully created a Order with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Order. 
		 */
		public Order testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Order" );

			Order entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Order with primary key" );
			msg.append( thePrimaryKey );
			
			OrderFetchOneSummary fetchOneSummary = new OrderFetchOneSummary( thePrimaryKey );

			try {
				entity = OrderService.getOrderInstance().getOrder( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Order " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Order.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Order." );

			StringBuilder msg = new StringBuilder( "Failed to update a Order : " );        
			Order entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Order." );

				// for use later on...
				thePrimaryKey = entity.getOrderId();

				OrderService proxy = OrderService.getOrderInstance();            
				proxy.updateOrder( entity );   

				LOGGER.info( "-- Successfully saved Order - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Order.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Order." );

			try{
			    Order entity = testRead(); 
				OrderService.getOrderInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Order with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Order with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Orders.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Orders:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Order : " );        
			List<Order> collection  = null;

			try {
				// call the static get method on the OrderService
				collection = OrderService.getOrderInstance().getAllOrder();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Order entity = null;            
					Iterator<Order> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getOrderId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

